# Rehace los niveles mal armados de Matemática I M9, M11, M12 y M13 (26/11/2026): una pantalla por idea, ejemplo y práctica propios.
import sys, json; sys.path.insert(0, 'tools/interactiva'); from armar import *
F=lambda md:m('fracciones',modo=md); FX=lambda md:m('fracciones_x',modo=md)
E=lambda md:m('enteros',modo=md); EX=lambda md:m('enteros_x',modo=md)
def m9n4(M):
  for t in M['niveles']['4']['leccion']['temas']:
    for b in t['explicacion']:
      if b['tipo']=='parrafo': b['texto']=b['texto'].replace(' También se simplifica al final.',' Cuando se pueda, conviene simplificar el resultado de cada término antes de seguir, así los números se mantienen chicos.').replace('(2/3)² es 2/3 × 2/3 = 4/9.','Por ejemplo, (2/3)² es 2/3 × 2/3, que da 4/9.')
L9={}
L9['1']={"temas":[
 T("Juntar y quitar partes",m('fraccion_barras'),m('fraccion_operar',op='suma'),("Sumar y restar fracciones","Solo se pueden juntar o quitar partes del mismo tamaño. Si las fracciones tienen el mismo denominador se suman o restan los numeradores; si no, antes se buscan fracciones equivalentes con un denominador común."),"Pensalo con una pizza: dos quintos y un quinto son tres quintos, porque las porciones son iguales. Pero un tercio y un cuarto no se pueden juntar así: hay que cortar las dos en doceavos, y recién ahí sumar cuatro doceavos y tres doceavos. El denominador nunca se suma, porque indica el tamaño de la porción.",["2/5 + 1/5 = 3/5.","1/3 + 1/4 = 4/12 + 3/12 = 7/12.","Cuidado: 1/3 + 1/4 no es 2/7."]),
 T("Enteros con fracciones",F('mixtos'),FX('mixtos'),("Operar con números mixtos","Un número mixto como 2 1/3 es un entero más una fracción. Para sumarlo o restarlo conviene pasarlo a fracción impropia, hacer la cuenta y volver a escribir el resultado como mixto."),"Para pasar 2 1/3 a fracción se piensa cuántos tercios hay en 2 enteros, que son 6, y se suma el que sobra: 7/3. Así todas las cantidades quedan en las mismas partes y se aplica lo que ya sabés. Al final, dividir el numerador por el denominador devuelve los enteros y lo que sobra.",["2 1/3 = 7/3.","23/6 = 3 5/6."])],
 "recuerda":[R("Para sumar o restar fracciones","las partes tienen que ser del mismo tamaño: igual denominador o un denominador común.","1/3 + 1/4 = 4/12 + 3/12 = 7/12"),R("El denominador","indica el tamaño de las partes, por eso no se suma ni se resta.","2/5 + 1/5 = 3/5, no 3/10"),R("Un número mixto","es un entero más una fracción y se puede escribir como fracción impropia.","2 1/3 = 7/3"),R("Para volver a escribir un resultado como número mixto","se divide el numerador por el denominador.","23/6 = 3 5/6")]}
L9['2']={"temas":[
 T("Una parte de una parte",m('fraccion_area'),m('fraccion_operar',op='producto'),("Multiplicar fracciones","Multiplicar dos fracciones es calcular una parte de otra parte. Se multiplican los numeradores entre sí y los denominadores entre sí, sin buscar denominador común."),"En el cuadrado, tomar 2/3 de 3/4 es pintar primero 3 de 4 columnas y después 2 de 3 filas de esa zona: quedan 6 cuadraditos de 12, es decir 1/2. Por eso la palabra «de» entre fracciones indica una multiplicación. Antes de multiplicar conviene simplificar un numerador con un denominador, porque así las cuentas son más cortas y el resultado sale casi listo.",["2/3 × 3/4 = 6/12 = 1/2.","«La mitad de 3/4» = 1/2 × 3/4 = 3/8.","Cuidado: se simplifica numerador con denominador, nunca dos numeradores."])],
 "recuerda":[R("Para multiplicar fracciones","se multiplican los numeradores entre sí y los denominadores entre sí.","2/3 × 3/4 = 6/12 = 1/2",formula="a/b × c/d = (a·c)/(b·d)"),R("La palabra «de» entre una fracción y otra","indica que hay que multiplicarlas.","1/2 de 3/4 = 3/8"),R("Simplificar antes de multiplicar","es dividir un numerador y un denominador por el mismo número.","4/9 × 3/8 = 1/3 × 1/2 = 1/6"),R("Un número entero","se puede escribir con denominador 1 para multiplicarlo por una fracción.","6 × 5/3 = 6/1 × 5/3 = 10")]}
L9['3']={"temas":[
 T("Dar vuelta una fracción",F('inverso'),FX('inverso'),("Inverso de una fracción","El inverso de una fracción se obtiene intercambiando el numerador y el denominador. Una fracción multiplicada por su inverso siempre da 1."),"5/8 por 8/5 da 40/40, que es 1, porque lo que se multiplica arriba es igual a lo de abajo. Un entero también tiene inverso: 3 es 3/1, así que su inverso es 1/3. El único número sin inverso es el 0, porque nada multiplicado por 0 da 1.",["Inverso de 5/8: 8/5.","Inverso de 3: 1/3.","El 0 no tiene inverso."]),
 T("¿Cuántas veces entra?",F('division'),m('fraccion_operar',op='division'),("Dividir fracciones","Dividir por una fracción es averiguar cuántas veces entra esa fracción en otra cantidad, y se resuelve multiplicando por el inverso de la segunda."),"Con 3 litros se llenan 6 botellas de medio litro, porque en cada litro entran dos mitades: 3 ÷ 1/2 = 3 × 2. Lo mismo vale para cualquier fracción: 3/4 ÷ 2/5 = 3/4 × 5/2 = 15/8. Por eso dividir por una fracción menor que 1 da un resultado más grande que el número del principio.",["3 ÷ 1/2 = 3 × 2 = 6.","3/4 ÷ 2/5 = 15/8.","Cuidado: se invierte solo la segunda fracción."])],
 "recuerda":[R("El inverso de una fracción","se obtiene dando vuelta numerador y denominador, y multiplicados dan 1.","5/8 × 8/5 = 1"),R("Dividir por una fracción","es lo mismo que multiplicar la primera por el inverso de la segunda.","3/4 ÷ 2/5 = 3/4 × 5/2 = 15/8",formula="a/b ÷ c/d = a/b × d/c"),R("Una división entre fracciones","responde cuántas veces entra una cantidad en otra, como cuántas botellas se llenan.","3 ÷ 1/2 = 6 botellas"),R("El cero","es el único número que no tiene inverso, porque nada por 0 da 1.","No existe 1/0")]}
guardar('contenido/matematica-1/mision-9/mision-9.json',L9,ajustes=m9n4)
L11={}
L11['1']={"temas":[
 T("Por debajo de cero",E('situacion'),EX('situacion'),("Números enteros","Los números enteros son los naturales, sus opuestos negativos y el cero. Sirven para expresar cantidades que están por encima o por debajo de un punto de referencia, que se toma como cero."),"Primero se decide qué es el cero en cada situación: la planta baja, el nivel del mar, el congelamiento del agua o no deber nada. Lo que está por encima o se tiene es positivo; lo que está por debajo o se debe, negativo, y se escribe con un signo menos adelante. Así −2 puede ser un subsuelo o dos grados bajo cero.",["−4 °C: cuatro grados bajo cero.","Subsuelo 2 → −2.","El 0 no es positivo ni negativo."]),
 T("Del otro lado del cero",E('opuesto'),EX('opuesto'),("Opuesto","El opuesto de un número entero es el que tiene el mismo valor con el signo cambiado; los dos están a la misma distancia del cero, uno de cada lado."),"Si subís 5 pisos y después bajás 5, volvés a la planta baja: 5 y −5 se compensan. Cambiar el signo dos veces devuelve el número original, por eso el opuesto de −8 es 8. El cero es el único número que es su propio opuesto.",["Opuesto de 7: −7.","Opuesto de −8: 8."])],
 "recuerda":[R("Los números enteros","son los positivos, los negativos y el cero, que funciona como referencia.","…, −2, −1, 0, 1, 2, …"),R("Un número negativo","indica una cantidad por debajo de la referencia y se escribe con signo menos.","4 grados bajo cero = −4 °C"),R("El opuesto de un número","tiene el mismo valor con el signo cambiado y está del otro lado del cero.","Opuesto de 7: −7"),R("El cero","no es positivo ni negativo, y es el único número igual a su opuesto.","Opuesto de 0: 0")]}
L11['3']={"temas":[
 T("Más a la derecha, más grande",E('comparar'),m('ordenar',modo='enteros'),("Comparar y ordenar enteros","De dos números enteros es mayor el que está más a la derecha en la recta. Para ordenar varios de menor a mayor se escriben de izquierda a derecha, como aparecen en la recta."),"Con los negativos el orden parece al revés: −2 es mayor que −7, porque está más cerca del cero. Pensalo con temperaturas: dos grados bajo cero es menos frío que siete bajo cero. Todo positivo es mayor que el cero y que cualquier negativo.",["−2 > −7.","−8 < −3 < 0 < 2 < 5."]),
 T("¿Cuántos hay entre dos?",E('intervalo'),EX('intervalo'),("Enteros de un intervalo","Los enteros que están entre dos números son los que quedan en la recta después del primero y antes del segundo; cuando se dice «entre», los extremos no se cuentan."),"Para no equivocarse conviene escribirlos todos, sin olvidar el cero, que también es un entero. Entre −4 y 3 están −3, −2, −1, 0, 1 y 2: son seis. Si en cambio dice «desde −4 hasta 3», se incluyen los extremos y son ocho.",["Entre −4 y 3: 6 enteros.","«Desde … hasta» incluye los extremos."])],
 "recuerda":[R("De dos números enteros","es mayor el que está más a la derecha en la recta numérica.","−2 > −7"),R("Entre dos números negativos","es mayor el que está más cerca del cero en la recta.","−3 > −8"),R("Para ordenar de menor a mayor","se escriben los enteros como aparecen en la recta, de izquierda a derecha.","−8 < −3 < 0 < 5"),R("Los enteros que hay entre dos números","no incluyen los extremos y hay que acordarse de contar el cero.","Entre −4 y 3 hay 6")]}
L11['4']={"temas":[
 T("La distancia al cero",E('absoluto'),EX('abs_opuesto'),("Valor absoluto","El valor absoluto de un número entero es su distancia al cero en la recta. Se escribe entre barras y nunca es negativo: |−6| = 6 y |6| = 6."),"Como es una distancia, no importa hacia qué lado está el número. Un buzo a 6 metros bajo el agua y una gaviota a 6 metros de altura están igual de lejos del nivel del mar. No hay que confundirlo con el opuesto: el opuesto de 5 es −5, pero su valor absoluto es 5.",["|−6| = 6.","Opuesto de 5: −5; |5| = 5."]),
 T("Cuánto subió o bajó",E('distancia'),EX('distancia'),("Diferencias entre enteros","La diferencia entre dos valores enteros, como dos temperaturas o dos alturas, es la distancia entre ellos en la recta numérica."),"Si están del mismo lado del cero, se restan sus valores absolutos; si están a distinto lado, se suman. A la mañana −4 °C y a la tarde 9 °C: la temperatura subió 4 grados hasta el cero y 9 más, en total 13. Dibujar la recta ayuda a no confundir los signos.",["De −4 a 9: subió 13.","De −7 a −2: subió 5."])],
 "recuerda":[R("El valor absoluto de un número","es su distancia al cero en la recta y nunca es negativo.","|−6| = 6"),R("El opuesto de un número","cambia su signo, y puede dar un resultado positivo o negativo.","Opuesto de 5: −5"),R("Un número y su opuesto","tienen el mismo valor absoluto, porque están a igual distancia del cero.","|5| = |−5| = 5"),R("La diferencia entre dos temperaturas","es la distancia entre ellas en la recta numérica.","De −4 °C a 9 °C: 13 grados")]}
guardar('contenido/matematica-1/mision-11/mision-11.json',L11)
L12={}
L12['1']={"temas":[
 T("Avanzar y retroceder",E('suma'),EX('suma'),("Sumar enteros","Sumar un positivo es avanzar hacia la derecha en la recta y sumar un negativo es retroceder hacia la izquierda. Si los dos sumandos tienen el mismo signo se suman sus valores absolutos y se deja ese signo; si tienen distinto signo se restan y queda el signo del de mayor valor absoluto."),"La regla resume lo que muestra la recta: (−8) + (−5) es retroceder 8 y otros 5, así que se llega a −13; (−15) + 9 es retroceder 15 y avanzar 9, y quedan 6 lugares a la izquierda: −6. Con varios sumandos conviene juntar primero los positivos y los negativos, porque la suma se puede reordenar.",["(−8) + (−5) = −13.","(−15) + 9 = −6.","Un número más su opuesto da 0."])],
 "recuerda":[R("Sumar un número negativo","es retroceder en la recta numérica, hacia la izquierda.","(−7) + 4 = −3"),R("Si los sumandos tienen el mismo signo","se suman los valores absolutos y se conserva ese signo.","(−8) + (−5) = −13"),R("Si los sumandos tienen distinto signo","se restan los valores absolutos y queda el signo del mayor.","(−15) + 9 = −6"),R("Con varios sumandos","se pueden juntar los positivos y los negativos antes de sumar.","−3 + 8 − 10 + 4 = 12 − 13 = −1")]}
L12['2']={"temas":[
 T("Restar es sumar el opuesto",E('resta'),EX('resta'),("Restar enteros","Para restar un número entero se suma su opuesto: a − b = a + (−b). Así toda resta se convierte en una suma y se resuelve con las reglas que ya conocés."),"3 − 8 es 3 + (−8) = −5. Y 3 − (−5) es 3 + 5 = 8: restar un negativo hace que el resultado aumente, igual que cuando te perdonan una deuda tu saldo sube. Por eso el orden importa: 8 − 3 da 5, pero 3 − 8 da −5.",["3 − 8 = 3 + (−8) = −5.","3 − (−5) = 3 + 5 = 8.","Cuidado: a − b y b − a dan resultados opuestos."]),
 T("La diferencia entre dos valores",E('distancia'),EX('distancia'),("Diferencia","La diferencia entre dos enteros, restando el mayor menos el menor, es la distancia que los separa en la recta."),"Entre una máxima de 8 °C y una mínima de −5 °C hay 8 − (−5) = 13 grados. La resta da el mismo número que contar los saltos en la recta. Si se resta al revés, sale −13: el signo dice en qué sentido se cambió, y el valor absoluto, cuánto.",["8 − (−5) = 13.","Mayor menos menor."])],
 "recuerda":[R("Restar un número entero","es lo mismo que sumarle al primero el opuesto del segundo.","3 − 8 = 3 + (−8) = −5",formula="a − b = a + (−b)"),R("Restar un número negativo","hace que el resultado aumente, porque equivale a sumar un positivo.","3 − (−5) = 8"),R("En la resta el orden importa","porque cambiar los números de lugar da el resultado opuesto.","8 − 3 = 5 · 3 − 8 = −5"),R("La diferencia entre dos enteros","restando mayor menos menor, es la distancia que los separa en la recta.","8 − (−5) = 13")]}
L12['3']={"temas":[
 T("Sacar los paréntesis",E('suprimir'),EX('suprimir'),("Suprimir paréntesis","En una cadena de sumas y restas con paréntesis, si delante del paréntesis hay un signo menos se cambian los signos de todos los términos de adentro al sacarlo; si hay un signo más, quedan igual."),"El menos resta todo lo que está adentro, y restar es sumar el opuesto de cada término. Por eso 8 − (3 − 5) es 8 − 3 + 5 = 10. El error más común es cambiar solo el primer signo. Con corchetes se trabaja de adentro hacia afuera, y para controlar se puede resolver primero lo de adentro: 8 − (−2) = 10.",["8 − (3 − 5) = 8 − 3 + 5 = 10.","2 + (3 − 5) = 2 + 3 − 5.","Cuidado: cambian todos los signos, no solo el primero."])],
 "recuerda":[R("Un signo menos delante del paréntesis","cambia el signo de todos los términos que están adentro al suprimirlo.","8 − (3 − 5) = 8 − 3 + 5 = 10"),R("Un signo más delante del paréntesis","deja todos los signos de adentro sin cambiar.","2 + (3 − 5) = 2 + 3 − 5"),R("Con paréntesis dentro de corchetes","se suprimen primero los de adentro y después los de afuera.","[5 − (2 − 4)] = [5 − 2 + 4] = 7"),R("Para controlar","se puede resolver primero lo de adentro y comparar los dos resultados.","8 − (−2) = 10")]}
guardar('contenido/matematica-1/mision-12/mision-12.json',L12)
L13={}
L13['1']={"temas":[
 T("Menos por menos",m('signos'),EX('producto'),("Multiplicar enteros","Para multiplicar enteros se multiplican los valores absolutos; el resultado es positivo si los signos son iguales y negativo si son distintos. Con varios factores, alcanza con contar los negativos: si son una cantidad par el producto es positivo, y si es impar, negativo."),"3 × (−4) es sumar tres veces −4, y da −12. Si se mira la tabla del −3 hacia abajo (−3 × 2 = −6, −3 × 1 = −3, −3 × 0 = 0), cada resultado sube 3; siguiendo el patrón, −3 × (−1) = 3. Por eso menos por menos da más: no es un capricho, sigue la regla de la tabla.",["(−3) × (−4) = 12.","(−2) × (−3) × (−4) = −24.","Si un factor es 0, el producto es 0."])],
 "recuerda":[R("Al multiplicar dos enteros","con signos iguales el resultado es positivo y con signos distintos es negativo.","(−3) × (−4) = 12"),R("Menos por menos da más","porque así se continúa el patrón de la tabla de multiplicar.","−3 × (−1) = 3"),R("Con varios factores","el producto es negativo si la cantidad de factores negativos es impar.","(−2) × (−3) × (−4) = −24"),R("Un producto con un factor cero","da siempre cero, sin importar los demás factores.","(−7) × 0 = 0")]}
L13['2']={"temas":[
 T("Dividir con signos",E('division'),EX('division'),("Dividir enteros","La división de enteros usa la misma regla de los signos que la multiplicación, porque es su operación inversa: (−42) ÷ (−7) = 6 porque 6 × (−7) = −42."),"Para no equivocarse con el signo, conviene comprobar multiplicando el cociente por el divisor: tiene que dar el dividendo exacto, con su signo. Si alguien dice que (−48) ÷ (−6) = −8, al comprobar sale (−8) × (−6) = 48 y no −48. Con el cero hay que tener cuidado: 0 ÷ (−5) = 0, pero dividir por cero no tiene resultado.",["(−63) ÷ 9 = −7.","0 ÷ (−5) = 0.","Cuidado: (−5) ÷ 0 no existe."])],
 "recuerda":[R("Al dividir enteros","se usa la misma regla de los signos que en la multiplicación.","(−42) ÷ (−7) = 6"),R("Para comprobar una división","se multiplica el cociente por el divisor y tiene que dar el dividendo.","6 × (−7) = −42"),R("El cero dividido por otro número","da cero siempre que ese número sea distinto de cero.","0 ÷ (−5) = 0"),R("Dividir por cero","no se puede, porque ningún número multiplicado por cero da otro distinto de cero.","(−5) ÷ 0 no existe")]}
L13['3']={"temas":[
 T("Cálculos combinados con signos",E('combinadas'),EX('combinadas'),("Combinadas con enteros","En los cálculos combinados con enteros se respeta la jerarquía de siempre y en cada multiplicación o división se aplica la regla de los signos."),"En 10 − 2 × (−6), primero 2 × (−6) = −12, y después 10 − (−12) = 22. La propiedad distributiva también vale con negativos: (−5) × (3 − 7) da lo mismo resolviendo el paréntesis, (−5) × (−4) = 20, que distribuyendo, −15 + 35 = 20. Separar en términos ayuda a no perder ningún signo.",["10 − 2 × (−6) = 22.","(−5) × (3 − 7) = 20."]),
 T("¿Qué está elevado?",E('cuadrado'),EX('cuadrado'),("Paréntesis en las potencias","Con paréntesis, (−3)² eleva toda la base −3 y da 9; sin paréntesis, −3² eleva solo el 3 y el signo menos queda afuera, así que da −9."),"Lo que queda elevado es lo que está pegado al exponente: si es un paréntesis, todo lo de adentro; si es un número, solo ese número. Es uno de los errores más frecuentes, y cambia el resultado entero de un cálculo. Por eso, cuando se reemplaza una letra por un negativo, se escribe entre paréntesis.",["(−3)² = 9.","−3² = −9."])],
 "recuerda":[R("La jerarquía con enteros","es la misma de siempre, aplicando la regla de los signos en cada producto.","10 − 2 × (−6) = 22"),R("La propiedad distributiva","también vale con negativos, cuidando el signo de cada producto.","(−5) × (3 − 7) = −15 + 35 = 20"),R("Con paréntesis, la potencia","eleva toda la base, incluido el signo menos.","(−3)² = 9"),R("Sin paréntesis","el exponente afecta solo al número y el signo menos queda afuera.","−3² = −9")]}
L13['4']={"temas":[
 T("Base negativa",m('potencias_explorar'),EX('potencia'),("Potencias de base negativa","Una potencia de base negativa da positivo si el exponente es par y negativo si es impar, porque cada par de factores negativos da un positivo."),"(−2)⁴ = 16 porque los cuatro factores negativos forman dos pares; (−2)⁵ = −32 porque queda uno sin pareja. Las propiedades de las potencias siguen valiendo: (−2)³ × (−2)² = (−2)⁵. Lo que nunca se puede es distribuir la potencia en una suma o una resta.",["(−2)⁴ = 16.","(−2)⁵ = −32."]),
 T("Raíces de enteros",E('raiz'),EX('raiz'),("Raíces de enteros","La raíz de índice impar de un número negativo existe y es negativa; la raíz de índice par de un número negativo no existe en los enteros."),"La raíz cúbica de −8 es −2, porque (−2)³ = −8. Pero √(−16) no existe, porque ningún entero elevado al cuadrado da negativo: tanto 4² como (−4)² dan 16. Antes de calcular una raíz hay que mirar el índice y el signo del número.",["∛(−8) = −2.","√(−16): no existe en los enteros."])],
 "recuerda":[R("Una potencia de base negativa","da positivo con exponente par y negativo con exponente impar.","(−2)⁴ = 16 · (−2)⁵ = −32"),R("Las propiedades de las potencias","valen también con base negativa, si la base está entre paréntesis.","(−2)³ × (−2)² = (−2)⁵"),R("La raíz de índice impar de un número negativo","existe y su resultado es un número negativo.","∛(−8) = −2"),R("La raíz cuadrada de un número negativo","no existe en los enteros, porque ningún cuadrado es negativo.","√(−16) no existe")]}
guardar('contenido/matematica-1/mision-13/mision-13.json',L13)
